BEGIN;

INSERT INTO posts (
  author_id,
  title,
  summary,
  content,
  image_url,
  region_id,
  budget_range_id,
  theme_id,
  season,
  companion,
  travel_date,
  tags,
  view_count,
  created_at,
  updated_at
)
SELECT
  u.id,
  seed.title,
  seed.summary,
  seed.content,
  seed.image_url,
  r.id,
  b.id,
  t.id,
  seed.season::season_enum,
  seed.companion::companion_enum,
  seed.travel_date::date,
  seed.tags,
  seed.view_count,
  seed.created_at::timestamptz,
  seed.updated_at::timestamptz
FROM (
  VALUES
    ('traveler01', '부산 쉬어가는 힐링 코스 067', '동백섬, 블루라인파크, 할매가야밀면까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 동백섬에서 시작해 블루라인파크까지 천천히 이어갔습니다. 식사는 할매가야밀면 근처로 잡고 숙소는 파크하얏트 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 힐링 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'healing', '여름', '친구', '2024-07-03', ARRAY['#부산', '#힐링', '#동백섬'], 180, '2026-06-12 09:00:00+09', '2026-06-12 09:00:00+09'),
    ('traveler01', '부산 가족 여행 짧은 동선 068', '부산엑스더스카이, 해운대해수욕장, 해운대암소갈비집까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 부산엑스더스카이에서 시작해 해운대해수욕장까지 천천히 이어갔습니다. 식사는 해운대암소갈비집 근처로 잡고 숙소는 파라다이스호텔 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 가족 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'over_300k', 'family', '봄', '가족', '2025-04-06', ARRAY['#부산', '#가족', '#부산엑스더스카이'], 217, '2026-06-12 06:00:00+09', '2026-06-12 06:00:00+09'),
    ('traveler01', '부산 노을 데이트 코스 069', '자갈치시장, 광안리해변, 할매가야밀면까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 자갈치시장에서 시작해 광안리해변까지 천천히 이어갔습니다. 식사는 할매가야밀면 근처로 잡고 숙소는 파크하얏트 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 데이트 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'date', '가을', '연인', '2026-10-09', ARRAY['#부산', '#데이트', '#자갈치시장'], 254, '2026-06-12 03:00:00+09', '2026-06-12 03:00:00+09'),
    ('traveler01', '부산 혼자 걷는 리셋 루트 070', '블루라인파크, 감천문화마을, 해운대암소갈비집까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 블루라인파크에서 시작해 감천문화마을까지 천천히 이어갔습니다. 식사는 해운대암소갈비집 근처로 잡고 숙소는 파라다이스호텔 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 혼행 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'under_100k', 'solo_trip', '겨울', '혼자', '2024-01-12', ARRAY['#부산', '#혼행', '#블루라인파크'], 291, '2026-06-12 00:00:00+09', '2026-06-12 00:00:00+09'),
    ('traveler01', '부산 맛집 중심 하루 코스 071', '해운대해수욕장, 해동용궁사, 할매가야밀면까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 해운대해수욕장에서 시작해 해동용궁사까지 천천히 이어갔습니다. 식사는 할매가야밀면 근처로 잡고 숙소는 파크하얏트 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 미식 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'gourmet', '여름', '친구', '2025-07-15', ARRAY['#부산', '#미식', '#해운대해수욕장'], 328, '2026-06-11 21:00:00+09', '2026-06-11 21:00:00+09'),
    ('traveler01', '부산 드라이브 한 바퀴 072', '광안리해변, 송도해상케이블카, 해운대암소갈비집까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 광안리해변에서 시작해 송도해상케이블카까지 천천히 이어갔습니다. 식사는 해운대암소갈비집 근처로 잡고 숙소는 파라다이스호텔 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 드라이브 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'drive', '봄', '가족', '2026-04-18', ARRAY['#부산', '#드라이브', '#광안리해변'], 365, '2026-06-11 18:00:00+09', '2026-06-11 18:00:00+09'),
    ('traveler01', '부산 기념일 숙소 코스 073', '감천문화마을, 흰여울문화마을, 할매가야밀면까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 감천문화마을에서 시작해 흰여울문화마을까지 천천히 이어갔습니다. 식사는 할매가야밀면 근처로 잡고 숙소는 파크하얏트 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 커플 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'over_300k', 'couple', '가을', '연인', '2024-10-21', ARRAY['#부산', '#커플', '#감천문화마을'], 402, '2026-06-11 15:00:00+09', '2026-06-11 15:00:00+09'),
    ('traveler01', '부산 맛집 중심 하루 코스 074', '해동용궁사, 동백섬, 해운대암소갈비집까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 해동용궁사에서 시작해 동백섬까지 천천히 이어갔습니다. 식사는 해운대암소갈비집 근처로 잡고 숙소는 파라다이스호텔 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 미식 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'under_100k', 'gourmet', '겨울', '친구', '2025-01-24', ARRAY['#부산', '#미식', '#해동용궁사'], 439, '2026-06-11 12:00:00+09', '2026-06-11 12:00:00+09'),
    ('traveler01', '부산 가족 여행 짧은 동선 075', '송도해상케이블카, 부산엑스더스카이, 할매가야밀면까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 송도해상케이블카에서 시작해 부산엑스더스카이까지 천천히 이어갔습니다. 식사는 할매가야밀면 근처로 잡고 숙소는 파크하얏트 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 가족 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'family', '봄', '가족', '2026-04-03', ARRAY['#부산', '#가족', '#송도해상케이블카'], 476, '2026-06-11 09:00:00+09', '2026-06-11 09:00:00+09'),
    ('traveler01', '부산 쉬어가는 힐링 코스 076', '흰여울문화마을, 자갈치시장, 해운대암소갈비집까지 묶은 부산 실제 여행 기록입니다.', '부산 여행은 흰여울문화마을에서 시작해 자갈치시장까지 천천히 이어갔습니다. 식사는 해운대암소갈비집 근처로 잡고 숙소는 파라다이스호텔 부산 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 힐링 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'healing', '가을', '혼자', '2024-10-06', ARRAY['#부산', '#힐링', '#흰여울문화마을'], 513, '2026-06-11 06:00:00+09', '2026-06-11 06:00:00+09'),
    ('traveler02', '제주 쉬어가는 힐링 코스 077', '만장굴, 제주돌문화공원, 돈사돈까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 만장굴에서 시작해 제주돌문화공원까지 천천히 이어갔습니다. 식사는 돈사돈 근처로 잡고 숙소는 메종글래드 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 힐링 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_100k_to_200k', 'healing', '여름', '친구', '2025-07-05', ARRAY['#제주', '#힐링', '#만장굴'], 270, '2026-06-11 23:00:00+09', '2026-06-11 23:00:00+09'),
    ('traveler02', '제주 가족 여행 짧은 동선 078', '카멜리아힐, 성산일출봉, 우진해장국까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 카멜리아힐에서 시작해 성산일출봉까지 천천히 이어갔습니다. 식사는 우진해장국 근처로 잡고 숙소는 신라호텔 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 가족 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'over_300k', 'family', '봄', '가족', '2026-04-08', ARRAY['#제주', '#가족', '#카멜리아힐'], 307, '2026-06-11 20:00:00+09', '2026-06-11 20:00:00+09'),
    ('traveler02', '제주 노을 데이트 코스 079', '한림공원, 우도, 돈사돈까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 한림공원에서 시작해 우도까지 천천히 이어갔습니다. 식사는 돈사돈 근처로 잡고 숙소는 메종글래드 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 데이트 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_200k_to_300k', 'date', '가을', '연인', '2024-10-11', ARRAY['#제주', '#데이트', '#한림공원'], 344, '2026-06-11 17:00:00+09', '2026-06-11 17:00:00+09'),
    ('traveler02', '제주 혼자 걷는 리셋 루트 080', '제주돌문화공원, 섭지코지, 우진해장국까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 제주돌문화공원에서 시작해 섭지코지까지 천천히 이어갔습니다. 식사는 우진해장국 근처로 잡고 숙소는 신라호텔 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 혼행 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'under_100k', 'solo_trip', '겨울', '혼자', '2025-01-14', ARRAY['#제주', '#혼행', '#제주돌문화공원'], 381, '2026-06-11 14:00:00+09', '2026-06-11 14:00:00+09'),
    ('traveler02', '제주 맛집 중심 하루 코스 081', '성산일출봉, 오설록티뮤지엄, 돈사돈까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 성산일출봉에서 시작해 오설록티뮤지엄까지 천천히 이어갔습니다. 식사는 돈사돈 근처로 잡고 숙소는 메종글래드 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 미식 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_100k_to_200k', 'gourmet', '여름', '친구', '2026-07-17', ARRAY['#제주', '#미식', '#성산일출봉'], 418, '2026-06-11 11:00:00+09', '2026-06-11 11:00:00+09'),
    ('traveler02', '제주 드라이브 한 바퀴 082', '우도, 협재해변, 우진해장국까지 묶은 제주 실제 여행 기록입니다.', '제주 여행은 우도에서 시작해 협재해변까지 천천히 이어갔습니다. 식사는 우진해장국 근처로 잡고 숙소는 신라호텔 제주 주변을 기준으로 정해 이동을 줄였습니다. 사진 찍는 시간과 쉬는 시간을 넉넉히 두어서 드라이브 여행으로 쓰기 좋았습니다.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_200k_to_300k', 'drive', '봄', '가족', '2024-04-20', ARRAY['#제주', '#드라이브', '#우도'], 455, '2026-06-11 08:00:00+09', '2026-06-11 08:00:00+09'),
